CREATE TABLE meal."trial_claims" (
  "id" uuid NOT NULL PRIMARY KEY,
  "claimed_at" timestamptz NOT NULL,
  "eligibility_evidence" jsonb NOT NULL,
  "user_id" uuid NOT NULL,
  "period_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."trial_claims" IS 'Факт использования trial. Уникально user; любое прошлое членство запрещает активацию';

CREATE TABLE meal."promotion_offers" (
  "id" uuid NOT NULL PRIMARY KEY,
  "code" text NOT NULL,
  "starts_at" timestamptz NOT NULL,
  "expires_at" timestamptz NOT NULL,
  "redeemed_at" timestamptz,
  "terms_snapshot" jsonb NOT NULL,
  "user_id" uuid NOT NULL,
  "price_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."promotion_offers" IS 'Индивидуальное предложение акции. Срок не перезапускается; отключение акции не отзывает выданный Pro';

CREATE TABLE meal."categories" (
  "id" uuid NOT NULL PRIMARY KEY,
  "code" text NOT NULL,
  "name" text NOT NULL,
  "parent_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."categories" IS 'Категории продуктов. Одна primary category, дополнительные связи отдельно';

CREATE TABLE meal."units" (
  "id" uuid NOT NULL PRIMARY KEY,
  "code" text NOT NULL,
  "dimension" text NOT NULL,
  "factor" numeric(24,8),
  "approximate" boolean NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."units" IS 'Единицы измерения. g/kg/ml/l/pcs/pack/serv и бытовые меры; точные и примерные различаются';

CREATE TABLE meal."ingredients" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "aliases" jsonb,
  "status" text NOT NULL,
  "default_storage_type" text,
  "primary_category_id" uuid NOT NULL,
  "default_unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ingredients" IS 'Системный ингредиент. Нормализованный продукт, не домашний остаток';

CREATE TABLE meal."ingredient_categories" (
  "id" uuid NOT NULL PRIMARY KEY,
  "ingredient_id" uuid NOT NULL,
  "category_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ingredient_categories" IS 'Дополнительные категории. Уникально ingredient+category';

CREATE TABLE meal."ingredient_variants" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "attributes" jsonb,
  "status" text NOT NULL,
  "ingredient_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ingredient_variants" IS 'Вариант ингредиента. Жирность, обработка, форма; не отдельная партия';

CREATE TABLE meal."brands" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "country_code" text,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."brands" IS 'Бренд. Один бренд может иметь много разных товаров';

CREATE TABLE meal."brand_products" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "package_quantity" numeric(24,8),
  "status" text NOT NULL,
  "variant_id" uuid NOT NULL,
  "brand_id" uuid,
  "package_unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."brand_products" IS 'Конкретный SKU и фасовка. Штрихкод относится к SKU, не к ингредиенту или бренду';

CREATE TABLE meal."product_barcodes" (
  "id" uuid NOT NULL PRIMARY KEY,
  "code" text NOT NULL,
  "format" text NOT NULL,
  "verified_at" timestamptz,
  "provenance" jsonb NOT NULL,
  "product_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."product_barcodes" IS 'Канонический штрихкод. Уникальный нормализованный code; конфликт не переписывается автоматически';

CREATE TABLE meal."composition_versions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "revision" integer NOT NULL,
  "composition_text" text,
  "kcal" numeric(24,8),
  "protein" numeric(24,8),
  "fat" numeric(24,8),
  "carbs" numeric(24,8),
  "basis_quantity" numeric(24,8) NOT NULL,
  "source" text NOT NULL,
  "confidence" numeric(24,8),
  "dietary_flags" jsonb,
  "ingredient_id" uuid,
  "variant_id" uuid,
  "product_id" uuid,
  "basis_unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."composition_versions" IS 'Версия состава и КБЖУ. Ровно один носитель; null не ноль; опубликованные/использованные версии неизменяемы';

CREATE TABLE meal."allergens" (
  "id" uuid NOT NULL PRIMARY KEY,
  "code" text NOT NULL,
  "name" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."allergens" IS 'Справочник аллергенов. Отсутствие связи не доказывает безопасность';

CREATE TABLE meal."composition_allergens" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "source" text NOT NULL,
  "confidence" numeric(24,8),
  "composition_id" uuid NOT NULL,
  "allergen_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."composition_allergens" IS 'Аллерген в версии состава. Уникально composition+allergen; contains/may_contain/unknown';

CREATE TABLE meal."unit_conversions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "factor_min" numeric(24,8) NOT NULL,
  "factor_max" numeric(24,8) NOT NULL,
  "precision" text NOT NULL,
  "source" text NOT NULL,
  "revision" integer NOT NULL,
  "ingredient_id" uuid,
  "product_id" uuid,
  "from_unit_id" uuid NOT NULL,
  "to_unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."unit_conversions" IS 'Версия пищевого пересчёта. Масса↔объём только при известных свойствах; упаковка привязана к товару';

CREATE TABLE meal."catalog_proposals" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "draft" jsonb NOT NULL,
  "provenance" jsonb NOT NULL,
  "submitted_at" timestamptz,
  "author_id" uuid NOT NULL,
  "product_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."catalog_proposals" IS 'Пользовательское предложение товара. Черновик приватен до модерации; правка не меняет старые composition snapshots';

CREATE TABLE meal."catalog_proposal_revisions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "revision" integer NOT NULL,
  "draft_snapshot" jsonb NOT NULL,
  "provenance" jsonb NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "proposal_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."catalog_proposal_revisions" IS 'Версия предложения товара. Решение модерации привязано к проверенной версии';

CREATE TABLE meal."catalog_merges" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "preview" jsonb NOT NULL,
  "applied_at" timestamptz,
  "reason" text,
  "source_ingredient_id" uuid,
  "target_ingredient_id" uuid,
  "source_product_id" uuid,
  "target_product_id" uuid,
  "actor_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."catalog_merges" IS 'Кандидат и решение объединения. Ровно одна пара одинакового типа; без циклов; старые ID остаются redirect, история не переписывается';

CREATE TABLE meal."storage_locations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "type" text NOT NULL,
  "name" text NOT NULL,
  "archived_at" timestamptz,
  "scope_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."storage_locations" IS 'Место хранения. Переименование не переносит партии и не меняет системный тип';

CREATE TABLE meal."inventory_batches" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "name" text NOT NULL,
  "quantity" numeric(24,8),
  "quantity_known" boolean NOT NULL,
  "precision" text NOT NULL,
  "package_state" text NOT NULL,
  "opened_at" timestamptz,
  "purchased_on" date,
  "expiry_on" date,
  "barcode_snapshot" text,
  "archived_at" timestamptz,
  "scope_id" uuid NOT NULL,
  "unit_id" uuid,
  "location_id" uuid,
  "ingredient_id" uuid,
  "variant_id" uuid,
  "product_id" uuid,
  "composition_id" uuid,
  "parent_batch_id" uuid,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."inventory_batches" IS 'Фактическая партия. Сырьё/готовая еда/заготовка; остаток >=0 либо unknown; известное количество требует единицы; производная партия хранит происхождение';

CREATE TABLE meal."inventory_operations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "effective_at" timestamptz NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "status" text NOT NULL,
  "idempotency_key" text NOT NULL,
  "preview_hash" text,
  "scope_id" uuid NOT NULL,
  "actor_id" uuid,
  "compensates_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."inventory_operations" IS 'Одно бытовое действие. Одна раскрываемая запись истории на действие; система может быть actor без user';

CREATE TABLE meal."inventory_movements" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity_delta" numeric(24,8),
  "before_snapshot" jsonb NOT NULL,
  "after_snapshot" jsonb NOT NULL,
  "base_version" bigint,
  "operation_id" uuid NOT NULL,
  "batch_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "compensates_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."inventory_movements" IS 'Движение партии. Append-only; корректировка новым движением; scope партии = scope операции';

CREATE TABLE meal."stocktakes" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "measured_at" timestamptz NOT NULL,
  "scope_id" uuid NOT NULL,
  "actor_id" uuid NOT NULL,
  "operation_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."stocktakes" IS 'Инвентаризация. Пропуск не обнуляет остатки';

CREATE TABLE meal."stocktake_lines" (
  "id" uuid NOT NULL PRIMARY KEY,
  "observed_quantity" numeric(24,8),
  "quantity_known" boolean NOT NULL,
  "reason" text,
  "base_version" bigint NOT NULL,
  "stocktake_id" uuid NOT NULL,
  "batch_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."stocktake_lines" IS 'Точный замер партии. Один замер партии в инвентаризации; конфликт со списанием проверяется';

CREATE TABLE meal."stock_reservations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8) NOT NULL,
  "status" text NOT NULL,
  "expires_at" timestamptz,
  "batch_id" uuid NOT NULL,
  "plan_entry_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."stock_reservations" IS 'Резерв под план. Не движение и не расход; одна область; корректируется после preview';

CREATE TABLE meal."preserve_details" (
  "id" uuid NOT NULL PRIMARY KEY,
  "type" text NOT NULL,
  "shelf_life_days" integer,
  "volume_per_unit" numeric(24,8),
  "notes" text,
  "tags" jsonb,
  "batch_id" uuid NOT NULL,
  "recipe_revision_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."preserve_details" IS 'Дополнительные данные заготовки. Одна запись на batch; количество не дублируется в независимом балансе';

CREATE TABLE meal."qr_labels" (
  "id" uuid NOT NULL PRIMARY KEY,
  "payload" jsonb NOT NULL,
  "revision" integer NOT NULL,
  "issued_at" timestamptz NOT NULL,
  "revoked_at" timestamptz,
  "preserve_id" uuid NOT NULL,
  "file_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."qr_labels" IS 'Версия этикетки заготовки. Offline минимальный snapshot; QR не даёт права на семейные данные';

CREATE TABLE meal."recipes" (
  "id" uuid NOT NULL PRIMARY KEY,
  "title" text NOT NULL,
  "status" text NOT NULL,
  "archived_at" timestamptz,
  "author_id" uuid NOT NULL,
  "scope_id" uuid NOT NULL,
  "base_recipe_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipes" IS 'Рецепт и самостоятельный вариант. Автор всегда user; публикация отдельна; вариант имеет собственные оценки';

CREATE TABLE meal."recipe_revisions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "revision" integer NOT NULL,
  "title" text NOT NULL,
  "portions" integer NOT NULL,
  "method" text NOT NULL,
  "nutrition_snapshot" jsonb,
  "timing" jsonb,
  "change_kind" text,
  "recipe_id" uuid NOT NULL,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipe_revisions" IS 'Неизменяемая версия рецепта. Уникально recipe+revision; изменение создаёт новую версию';

CREATE TABLE meal."recipe_ingredients" (
  "id" uuid NOT NULL PRIMARY KEY,
  "position" integer NOT NULL,
  "quantity" numeric(24,8),
  "optional" boolean NOT NULL,
  "requirements" jsonb,
  "substitution_rules" jsonb,
  "revision_id" uuid NOT NULL,
  "ingredient_id" uuid,
  "variant_id" uuid,
  "product_id" uuid,
  "source_recipe_id" uuid,
  "unit_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipe_ingredients" IS 'Ингредиент версии. Количество может быть unknown; пищевой источник однозначен; readiness по обязательным позициям';

CREATE TABLE meal."recipe_steps" (
  "id" uuid NOT NULL PRIMARY KEY,
  "position" integer NOT NULL,
  "text" text NOT NULL,
  "duration_seconds" integer,
  "temperature" numeric(24,8),
  "equipment_requirements" jsonb,
  "revision_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipe_steps" IS 'Шаг версии. Уникально revision+position; локальный таймер не завершает шаг';

CREATE TABLE meal."cooking_attempts" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "started_at" timestamptz NOT NULL,
  "completed_at" timestamptz,
  "recipe_snapshot" jsonb NOT NULL,
  "output_snapshot" jsonb,
  "confirmed_duration" integer,
  "private_note" text,
  "scope_id" uuid NOT NULL,
  "actor_id" uuid NOT NULL,
  "revision_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."cooking_attempts" IS 'Отдельная попытка готовки. Старт не списывает; snapshot содержит замены/товары/точность; неудачный повтор — новая попытка';

CREATE TABLE meal."cooking_steps" (
  "id" uuid NOT NULL PRIMARY KEY,
  "position" integer NOT NULL,
  "status" text NOT NULL,
  "started_at" timestamptz,
  "ended_at" timestamptz,
  "timer_deadline" timestamptz,
  "timer_paused_seconds" integer,
  "private_note" text,
  "attempt_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."cooking_steps" IS 'Прогресс шага. Сохранение черновика; один локальный таймер по принятой области ограничения';

CREATE TABLE meal."cooking_inputs" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8) NOT NULL,
  "composition_snapshot" jsonb NOT NULL,
  "precision" text NOT NULL,
  "attempt_id" uuid NOT NULL,
  "batch_id" uuid NOT NULL,
  "movement_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."cooking_inputs" IS 'Фактически использованная партия. Движение относится к этой же области; использованное готовое блюдо не расходует сырьё повторно';

CREATE TABLE meal."cooking_outputs" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8) NOT NULL,
  "yield_snapshot" jsonb NOT NULL,
  "attempt_id" uuid NOT NULL,
  "batch_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."cooking_outputs" IS 'Выход готовки. Разные места/состояния — отдельные партии; failed не создаёт доступного выхода';

CREATE TABLE meal."cooking_time_reviews" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "rule_version" text NOT NULL,
  "reason" text,
  "scale_snapshot" jsonb NOT NULL,
  "attempt_id" uuid NOT NULL,
  "reviewed_by" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."cooking_time_reviews" IS 'Пригодность замера времени. Выброс сохраняется; статистика разделяется по версии/способу/масштабу';

CREATE TABLE meal."meal_plans" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "archived_at" timestamptz,
  "scope_id" uuid NOT NULL,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."meal_plans" IS 'План питания. План не изменяет фактический запас';

CREATE TABLE meal."plan_revisions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "revision" integer NOT NULL,
  "starts_on" date NOT NULL,
  "ends_on" date NOT NULL,
  "timezone" text NOT NULL,
  "status" text NOT NULL,
  "plan_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."plan_revisions" IS 'Версия плана. Год по реальным датам; период и timezone сохранены';

CREATE TABLE meal."plan_rules" (
  "id" uuid NOT NULL PRIMARY KEY,
  "rule" jsonb NOT NULL,
  "exceptions" jsonb,
  "portions" integer NOT NULL,
  "starts_on" date NOT NULL,
  "ends_on" date NOT NULL,
  "revision_id" uuid NOT NULL,
  "recipe_revision_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."plan_rules" IS 'Повторение блюда. Правило создаёт даты, не множитель 52; сценарий 52/53 сохраняется';

CREATE TABLE meal."plan_entries" (
  "id" uuid NOT NULL PRIMARY KEY,
  "date" date NOT NULL,
  "meal" text NOT NULL,
  "portions" integer NOT NULL,
  "substitutions" jsonb,
  "manual" boolean NOT NULL,
  "locked" boolean NOT NULL,
  "revision_id" uuid NOT NULL,
  "rule_id" uuid,
  "recipe_revision_id" uuid,
  "batch_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."plan_entries" IS 'Конкретный приём пищи. Версия и выбранные источники фиксированы; реальные покупки не удаляются с планом';

CREATE TABLE meal."plan_portions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "portions" numeric(24,8) NOT NULL,
  "size" text NOT NULL,
  "entry_id" uuid NOT NULL,
  "user_id" uuid,
  "profile_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."plan_portions" IS 'Порции участников плана. Ровно один получатель; это план, не личный дневник и не факт еды';

CREATE TABLE meal."plan_previews" (
  "id" uuid NOT NULL PRIMARY KEY,
  "input_versions" jsonb NOT NULL,
  "result_snapshot" jsonb NOT NULL,
  "accepted_at" timestamptz,
  "applied_at" timestamptz,
  "expires_at" timestamptz NOT NULL,
  "revision_id" uuid NOT NULL,
  "actor_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."plan_previews" IS 'Предпросмотр перерасчёта. Перед commit повторная проверка версий, прав и остатков';

CREATE TABLE meal."shopping_lists" (
  "id" uuid NOT NULL PRIMARY KEY,
  "title" text NOT NULL,
  "status" text NOT NULL,
  "scope_id" uuid NOT NULL,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."shopping_lists" IS 'Список покупок. Ручное и купленное не перезаписывается пересчётом';

CREATE TABLE meal."shopping_items" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "quantity" numeric(24,8),
  "requirements" jsonb NOT NULL,
  "allow_analog" boolean NOT NULL,
  "manual" boolean NOT NULL,
  "status" text NOT NULL,
  "list_id" uuid NOT NULL,
  "ingredient_id" uuid,
  "product_id" uuid,
  "unit_id" uuid,
  "assigned_membership_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."shopping_items" IS 'Потребность в покупке. Точная марка или аналог различаются; назначение только в своей семье';

CREATE TABLE meal."shopping_contributions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8) NOT NULL,
  "portions" integer NOT NULL,
  "substitutions" jsonb NOT NULL,
  "item_id" uuid NOT NULL,
  "entry_id" uuid,
  "recipe_revision_id" uuid,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."shopping_contributions" IS 'Вклад рецепта в потребность. Сохранён источник потребности; удаление плана не отменяет покупку';

CREATE TABLE meal."shopping_allocations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8) NOT NULL,
  "item_id" uuid NOT NULL,
  "purchase_line_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."shopping_allocations" IS 'Закрытие потребности покупкой. Одно купленное количество распределяется один раз; избыток остаётся запасом';

CREATE TABLE meal."stores" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "external_ref" text,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."stores" IS 'Магазин. Не хранить произвольный адрес пользователя как публичный атрибут магазина';

CREATE TABLE meal."receipts" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "fiscal_fingerprint" text,
  "purchased_at" timestamptz,
  "raw_review_snapshot" jsonb NOT NULL,
  "scope_id" uuid NOT NULL,
  "created_by" uuid NOT NULL,
  "store_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."receipts" IS 'Исходный продуктовый чек. Карточка семейного чека всем участникам; финансовые действия дополнительно Pro';

CREATE TABLE meal."receipt_lines" (
  "id" uuid NOT NULL PRIMARY KEY,
  "position" integer NOT NULL,
  "raw_name" text NOT NULL,
  "quantity" numeric(24,8),
  "amount_minor" bigint,
  "discount_minor" bigint,
  "is_food" boolean NOT NULL,
  "provenance" jsonb NOT NULL,
  "receipt_id" uuid NOT NULL,
  "product_id" uuid,
  "ingredient_id" uuid,
  "unit_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."receipt_lines" IS 'Проверенная строка чека. OCR не является подтверждением; непродуктовое не пополняет пищевой запас';

CREATE TABLE meal."purchases" (
  "id" uuid NOT NULL PRIMARY KEY,
  "purchased_at" timestamptz NOT NULL,
  "status" text NOT NULL,
  "source" text NOT NULL,
  "scope_id" uuid NOT NULL,
  "actor_id" uuid NOT NULL,
  "store_id" uuid,
  "receipt_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."purchases" IS 'Факт покупки. Поздний чек связывается с существующим фактом по подтверждению';

CREATE TABLE meal."purchase_lines" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "quantity" numeric(24,8),
  "amount_minor" bigint,
  "original_amount_minor" bigint,
  "is_food" boolean NOT NULL,
  "purchase_id" uuid NOT NULL,
  "receipt_line_id" uuid,
  "ingredient_id" uuid,
  "product_id" uuid,
  "unit_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."purchase_lines" IS 'Купленная позиция. Покупка, денежный расход и поступление — отдельные факты';

CREATE TABLE meal."stock_intakes" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8) NOT NULL,
  "purchase_line_id" uuid NOT NULL,
  "batch_id" uuid NOT NULL,
  "movement_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."stock_intakes" IS 'Поступление купленного в запас. Повтор чека не создаёт второе поступление; область покупки и партии согласована';

CREATE TABLE meal."purchase_returns" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8) NOT NULL,
  "amount_minor" bigint,
  "reason" text NOT NULL,
  "returned_at" timestamptz NOT NULL,
  "purchase_line_id" uuid NOT NULL,
  "operation_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."purchase_returns" IS 'Возврат товара. Возврат денег и изменение запаса связаны явно; без автоматического воскрешения съеденного';

CREATE TABLE meal."expenses" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "amount_minor" bigint NOT NULL,
  "currency" text NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "finance_consent_at" timestamptz NOT NULL,
  "scope_id" uuid NOT NULL,
  "purchase_line_id" uuid,
  "return_id" uuid,
  "actor_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."expenses" IS 'Денежная запись Pro. Один первичный расход на источник; стоимость готовки не создаёт повторный расход';

CREATE TABLE meal."budgets" (
  "id" uuid NOT NULL PRIMARY KEY,
  "amount_minor" bigint NOT NULL,
  "currency" text NOT NULL,
  "starts_on" date NOT NULL,
  "ends_on" date NOT NULL,
  "scope_id" uuid NOT NULL,
  "category_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."budgets" IS 'Бюджет. Оценка будущих покупок отдельно от фактических трат';

CREATE TABLE meal."price_observations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "amount_minor" bigint NOT NULL,
  "quantity" numeric(24,8) NOT NULL,
  "observed_at" timestamptz NOT NULL,
  "provenance" jsonb NOT NULL,
  "eligible_for_aggregate" boolean NOT NULL,
  "scope_id" uuid NOT NULL,
  "ingredient_id" uuid NOT NULL,
  "purchase_line_id" uuid,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."price_observations" IS 'Источник цены. Личные источники не выдаются семье или публичному API';

CREATE TABLE meal."price_aggregates" (
  "id" uuid NOT NULL PRIMARY KEY,
  "median_minor" bigint NOT NULL,
  "calculated_at" timestamptz NOT NULL,
  "sample_count" integer NOT NULL,
  "method_version" text NOT NULL,
  "source_window" jsonb NOT NULL,
  "ingredient_id" uuid NOT NULL,
  "unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."price_aggregates" IS 'Версия ориентировочной цены. Обезличенный агрегат только допустимых источников; не раскрывает личные чеки';

CREATE TABLE meal."cost_allocations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "amount_minor" bigint NOT NULL,
  "precision" text NOT NULL,
  "source_snapshot" jsonb NOT NULL,
  "movement_id" uuid NOT NULL,
  "purchase_line_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."cost_allocations" IS 'Себестоимость использованного. Распределение стоимости, не новый платёж; составной выход переносит стоимость';

CREATE TABLE meal."nutrition_profiles" (
  "id" uuid NOT NULL PRIMARY KEY,
  "restrictions" jsonb,
  "likes" jsonb,
  "dislikes" jsonb,
  "allergen_mode" text NOT NULL,
  "profile_data" jsonb,
  "user_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."nutrition_profiles" IS 'Личные предпочтения питания. Одна запись на user; личный профиль не открывается семье автоматически';

CREATE TABLE meal."profile_allergens" (
  "id" uuid NOT NULL PRIMARY KEY,
  "severity" text,
  "note" text,
  "nutrition_profile_id" uuid,
  "family_profile_id" uuid,
  "allergen_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."profile_allergens" IS 'Ограничения человека. Ровно один профиль; детские поля выключены до guardian gate';

CREATE TABLE meal."equipment" (
  "id" uuid NOT NULL PRIMARY KEY,
  "code" text NOT NULL,
  "name" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."equipment" IS 'Справочник оборудования. Отсутствие настройки не равно отсутствию техники';

CREATE TABLE meal."profile_equipment" (
  "id" uuid NOT NULL PRIMARY KEY,
  "availability" text NOT NULL,
  "scope_id" uuid NOT NULL,
  "equipment_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."profile_equipment" IS 'Оборудование в области. Уникально scope+equipment; yes/no/unknown';

CREATE TABLE meal."nutrition_targets" (
  "id" uuid NOT NULL PRIMARY KEY,
  "starts_on" date NOT NULL,
  "ends_on" date,
  "targets" jsonb NOT NULL,
  "source" text NOT NULL,
  "profile_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."nutrition_targets" IS 'История личных целей. Без медицинских обещаний; child auto-calorie targets запрещены';

CREATE TABLE meal."portion_proposals" (
  "id" uuid NOT NULL PRIMARY KEY,
  "allocation_key" text NOT NULL,
  "available_at" timestamptz NOT NULL,
  "due_at" timestamptz NOT NULL,
  "state" text NOT NULL,
  "decision_at" timestamptz,
  "confirmation_method" text,
  "nutrition_snapshot" jsonb NOT NULL,
  "quantity_snapshot" jsonb NOT NULL,
  "recipient_id" uuid NOT NULL,
  "attempt_id" uuid NOT NULL,
  "output_id" uuid,
  "profile_id" uuid,
  "allocation_operation_id" uuid NOT NULL,
  "issued_quantity" numeric(24,8) NOT NULL,
  "issued_unit_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."portion_proposals" IS 'Предложенная личная порция. Уникально attempt+recipient+allocation_key; при назначении однократно списывается готовая еда; 24ч от доступности, CAS pending→decision; отказ/отмена дневника не возвращают запас';

CREATE TABLE meal."diary_entries" (
  "id" uuid NOT NULL PRIMARY KEY,
  "eaten_at" timestamptz NOT NULL,
  "meal" text NOT NULL,
  "state" text NOT NULL,
  "confirmation_method" text NOT NULL,
  "note" text,
  "nutrition_snapshot" jsonb NOT NULL,
  "owner_id" uuid NOT NULL,
  "proposal_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."diary_entries" IS 'Приватная запись дневника. Уникально proposal при наличии; отмена auto-confirm исключает вклад без возврата сырья';

CREATE TABLE meal."diary_components" (
  "id" uuid NOT NULL PRIMARY KEY,
  "quantity" numeric(24,8),
  "food_snapshot" jsonb NOT NULL,
  "nutrition_snapshot" jsonb NOT NULL,
  "entry_id" uuid NOT NULL,
  "batch_id" uuid,
  "movement_id" uuid,
  "unit_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."diary_components" IS 'Часть тарелки. Snapshot разрешённого источника; привязка к семье не даёт права читать семью после выхода';

CREATE TABLE meal."ai_rule_versions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "version" bigint NOT NULL,
  "config" jsonb NOT NULL,
  "effective_at" timestamptz NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE meal."ai_rule_versions" IS 'Правила стоимости и безопасности. Историческое правило операции не меняется задним числом';

CREATE TABLE meal."ai_conversations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "title" text NOT NULL,
  "archived_at" timestamptz,
  "user_id" uuid NOT NULL,
  "scope_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_conversations" IS 'Беседа. Контекст фиксирован; смена вкладки не переназначает беседу';

CREATE TABLE meal."ai_tasks" (
  "id" uuid NOT NULL PRIMARY KEY,
  "goal" text NOT NULL,
  "status" text NOT NULL,
  "preview" jsonb NOT NULL,
  "accepted_at" timestamptz,
  "accepted_cost" bigint NOT NULL,
  "agreement_snapshot" jsonb NOT NULL,
  "conversation_id" uuid NOT NULL,
  "rule_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_tasks" IS 'Цель в беседе. Новая цель требует preview; продолжение той же — без повторного ценового диалога';

CREATE TABLE meal."ai_intervals" (
  "id" uuid NOT NULL PRIMARY KEY,
  "starts_at" timestamptz NOT NULL,
  "ends_at" timestamptz NOT NULL,
  "clarifications_used" bigint NOT NULL,
  "cost" integer NOT NULL,
  "status" text NOT NULL,
  "task_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_intervals" IS 'Оплачиваемый интервал. 10 минут с сообщения; молчание и ожидание модели не создают интервал';

CREATE TABLE meal."ai_messages" (
  "id" uuid NOT NULL PRIMARY KEY,
  "role" text NOT NULL,
  "body" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "client_message_key" text NOT NULL,
  "conversation_id" uuid NOT NULL,
  "interval_id" uuid,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_messages" IS 'Сообщение беседы. До двух уточнений; повторы client_message_key не оплачиваются';

CREATE TABLE meal."ai_operations" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "result_snapshot" jsonb,
  "started_at" timestamptz,
  "finished_at" timestamptz,
  "provider_cost" numeric(24,8),
  "idempotency_key" text NOT NULL,
  "interval_id" uuid NOT NULL,
  "message_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_operations" IS 'Выполнение запроса. Результат открывается бесплатно; retry модели не новая пользовательская операция';

CREATE TABLE meal."ai_quota_periods" (
  "id" uuid NOT NULL PRIMARY KEY,
  "starts_at" timestamptz NOT NULL,
  "ends_at" timestamptz NOT NULL,
  "granted_actions" bigint NOT NULL,
  "allocation_snapshot" jsonb NOT NULL,
  "subscription_id" uuid,
  "family_coverage_id" uuid,
  "trial_claim_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_quota_periods" IS 'Период подписочной AI-квоты. Один источник выдачи; новая семья/страховка не порождает лишнюю квоту';

CREATE TABLE meal."ai_buckets" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "granted" bigint NOT NULL,
  "expires_at" timestamptz,
  "balance_projection" bigint NOT NULL,
  "user_id" uuid,
  "family_id" uuid,
  "quota_period_id" uuid,
  "order_id" uuid,
  "reserved_projection" bigint NOT NULL DEFAULT 0,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_buckets" IS 'Корзина действий. XOR user/family; purchased не сгорает и не делится автоматически';

CREATE TABLE meal."ai_ledger" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "delta" bigint NOT NULL,
  "reserved_delta" bigint NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "idempotency_key" text NOT NULL,
  "bucket_id" uuid NOT NULL,
  "operation_id" uuid,
  "compensates_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_ledger" IS 'Движение AI-действий. Append-only; reserve/capture/release/refund; остатки не отрицательны';

CREATE TABLE meal."ai_transfers" (
  "id" uuid NOT NULL PRIMARY KEY,
  "amount" bigint NOT NULL,
  "status" text NOT NULL,
  "accepted_at" timestamptz,
  "expires_at" timestamptz NOT NULL,
  "from_bucket_id" uuid NOT NULL,
  "to_bucket_id" uuid NOT NULL,
  "donor_id" uuid NOT NULL,
  "recipient_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_transfers" IS 'Передача подписочных действий. Целое количество, согласие донора; срок текущего периода';

CREATE TABLE meal."ai_reserve_consents" (
  "id" uuid NOT NULL PRIMARY KEY,
  "accepted_at" timestamptz NOT NULL,
  "actions" bigint NOT NULL,
  "preview_hash" text NOT NULL,
  "user_id" uuid NOT NULL,
  "task_id" uuid NOT NULL,
  "bucket_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_reserve_consents" IS 'Разрешение семейного резерва. Отдельное проверяемое согласие; продолжение беседы не даёт его автоматически';

CREATE TABLE meal."ai_safety_events" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "confidence" numeric(24,8),
  "evidence" jsonb NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "revoked_at" timestamptz,
  "user_id" uuid NOT NULL,
  "operation_id" uuid,
  "rule_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."ai_safety_events" IS 'Проверяемый AI-инцидент. Оффтоп/тарифный отказ не strike; отменённое исключается из лестницы санкций';

CREATE TABLE meal."chat_threads" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "family_id" uuid,
  "recipient_id" uuid,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."chat_threads" IS 'Семейный или служебный чат. Один семейный чат; support метка системная и неизменяемая';

CREATE TABLE meal."chat_messages" (
  "id" uuid NOT NULL PRIMARY KEY,
  "body" text NOT NULL,
  "sent_at" timestamptz NOT NULL,
  "edited_at" timestamptz,
  "removed_for_all_at" timestamptz,
  "album_key" text,
  "thread_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "reply_to_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."chat_messages" IS 'Сообщение чата. История семейного чата ограничена периодом вступления; удаление не рвёт ответы';

CREATE TABLE meal."chat_revisions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "body" text NOT NULL,
  "revision" integer NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "message_id" uuid NOT NULL,
  "actor_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."chat_revisions" IS 'Версия сообщения. Пометка редактирования и защищённая история';

CREATE TABLE meal."chat_reactions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "reaction" text NOT NULL,
  "message_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."chat_reactions" IS 'Реакция на сообщение. Уникальность message+user+reaction; меняет автор реакции';

CREATE TABLE meal."chat_receipts" (
  "id" uuid NOT NULL PRIMARY KEY,
  "delivered_at" timestamptz,
  "read_at" timestamptz,
  "message_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."chat_receipts" IS 'Доставка и прочтение. Статус только по доказанному событию, не предположению';

CREATE TABLE meal."chat_pins" (
  "id" uuid NOT NULL PRIMARY KEY,
  "pinned_at" timestamptz NOT NULL,
  "unpinned_at" timestamptz,
  "message_id" uuid NOT NULL,
  "actor_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."chat_pins" IS 'Закреплённое сообщение. Проверка доступа к тому же чату';

CREATE TABLE meal."chat_drafts" (
  "id" uuid NOT NULL PRIMARY KEY,
  "body" text NOT NULL,
  "updated_at" timestamptz,
  "thread_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."chat_drafts" IS 'Черновик сообщения. Приватен автору; одна запись thread+user';

CREATE TABLE meal."support_tickets" (
  "id" uuid NOT NULL PRIMARY KEY,
  "public_number" text NOT NULL,
  "category" text NOT NULL,
  "status" text NOT NULL,
  "subject" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "closed_at" timestamptz,
  "requester_id" uuid NOT NULL,
  "assignee_id" uuid,
  "thread_id" uuid,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."support_tickets" IS 'Обращение поддержки. Очередь и staff назначение не раскрывают внутренние финансовые данные';

CREATE TABLE meal."support_events" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "before_snapshot" jsonb NOT NULL,
  "after_snapshot" jsonb NOT NULL,
  "reason" text,
  "recorded_at" timestamptz NOT NULL,
  "ticket_id" uuid NOT NULL,
  "actor_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."support_events" IS 'История состояния и назначения тикета. Append-only; reopen и смена ответственного отдельные события; пользовательская проекция исключает внутренний контекст';

CREATE TABLE meal."support_messages" (
  "id" uuid NOT NULL PRIMARY KEY,
  "body" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "internal" boolean NOT NULL,
  "ticket_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."support_messages" IS 'Ответ в тикете. Внутренний комментарий не отдаётся заявителю';

CREATE TABLE meal."helper_applications" (
  "id" uuid NOT NULL PRIMARY KEY,
  "name" text NOT NULL,
  "contribution" text NOT NULL,
  "availability" text NOT NULL,
  "status" text NOT NULL,
  "user_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."helper_applications" IS 'Анкета помощи. Принятие анкеты не выдаёт staff роль';

CREATE TABLE meal."notification_preferences" (
  "id" uuid NOT NULL PRIMARY KEY,
  "category" text NOT NULL,
  "channel" text NOT NULL,
  "enabled" boolean NOT NULL,
  "quiet_hours" jsonb NOT NULL,
  "timezone" text NOT NULL,
  "urgent_opt_in" boolean NOT NULL,
  "user_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."notification_preferences" IS 'Категории и каналы. Маркетинг требует отдельного согласия; quiet hours не отменяют критичные исключения';

CREATE TABLE meal."push_subscriptions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "endpoint_encrypted" text NOT NULL,
  "keys_encrypted" text NOT NULL,
  "revoked_at" timestamptz,
  "user_id" uuid NOT NULL,
  "session_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."push_subscriptions" IS 'Устройство Web Push. Секреты и endpoint не в обычных логах';

CREATE TABLE meal."notifications" (
  "id" uuid NOT NULL PRIMARY KEY,
  "category" text NOT NULL,
  "priority" text NOT NULL,
  "payload_minimized" jsonb NOT NULL,
  "dedup_key" text NOT NULL,
  "available_at" timestamptz NOT NULL,
  "read_at" timestamptz,
  "fullscreen_seen_at" timestamptz,
  "user_id" uuid NOT NULL,
  "ownership_transfer_id" uuid,
  "announcement_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."notifications" IS 'Внутреннее уведомление. Уникальная доставка события; fullscreen при назначении не согласие на роль';

CREATE TABLE meal."notification_deliveries" (
  "id" uuid NOT NULL PRIMARY KEY,
  "channel" text NOT NULL,
  "status" text NOT NULL,
  "scheduled_at" timestamptz NOT NULL,
  "sent_at" timestamptz,
  "provider_ref" text,
  "attempt_no" integer NOT NULL,
  "notification_id" uuid NOT NULL,
  "campaign_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."notification_deliveries" IS 'Попытки отправки. Дедупликация, тихие часы, retries; seen/read и delivery различны';

CREATE TABLE meal."announcements" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "revision" integer NOT NULL,
  "pages" jsonb NOT NULL,
  "status" text NOT NULL,
  "publish_at" timestamptz,
  "author_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."announcements" IS 'Версия новости и объявления. Сервисное сообщение не превращается в юридическое согласие';

CREATE TABLE meal."mail_campaigns" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "scheduled_at" timestamptz,
  "audience_snapshot" jsonb NOT NULL,
  "test_result" jsonb,
  "announcement_id" uuid NOT NULL,
  "created_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."mail_campaigns" IS 'План email-рассылки. Отмена только неотправленного; маркетинговое согласие перепроверяется при отправке';

CREATE TABLE meal."recipe_publications" (
  "id" uuid NOT NULL PRIMARY KEY,
  "published_at" timestamptz NOT NULL,
  "unpublished_at" timestamptz,
  "revision_id" uuid NOT NULL,
  "decision_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipe_publications" IS 'Публичная версия рецепта. Только проверенная версия; private/family авторство сохраняется';

CREATE TABLE meal."recipe_ratings" (
  "id" uuid NOT NULL PRIMARY KEY,
  "value" smallint NOT NULL,
  "confirmed_at" timestamptz NOT NULL,
  "recipe_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "attempt_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipe_ratings" IS 'Подтверждённая оценка. Уникально recipe+user; 1–5 неизменяемо после фиксации; готовка этого пользователя/рецепта';

CREATE TABLE meal."recipe_comments" (
  "id" uuid NOT NULL PRIMARY KEY,
  "body" text NOT NULL,
  "edited_at" timestamptz,
  "removed_at" timestamptz,
  "recipe_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "attempt_id" uuid NOT NULL,
  "reply_to_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipe_comments" IS 'Комментарий и ответ. Комментарий/медиа после готовки; edit с отметкой; связи ответов сохраняются';

CREATE TABLE meal."comment_revisions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "body" text NOT NULL,
  "revision" integer NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "comment_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."comment_revisions" IS 'Версия комментария. История изменения не раскрывается произвольно';

CREATE TABLE meal."comment_reactions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "reaction" text NOT NULL,
  "comment_id" uuid NOT NULL,
  "user_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."comment_reactions" IS 'Реакция на комментарий. Изменяет автор реакции; дедупликация';

CREATE TABLE meal."author_follows" (
  "id" uuid NOT NULL PRIMARY KEY,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "follower_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."author_follows" IS 'Подписка на автора. Уникально follower+author; не тарифная подписка';

CREATE TABLE meal."recipe_bookmarks" (
  "id" uuid NOT NULL PRIMARY KEY,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "user_id" uuid NOT NULL,
  "recipe_id" uuid NOT NULL,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recipe_bookmarks" IS 'Сохранённый рецепт. Личная подборка не расширяет доступ к рецепту';

CREATE TABLE meal."achievement_rules" (
  "id" uuid NOT NULL PRIMARY KEY,
  "code" text NOT NULL,
  "revision" integer NOT NULL,
  "condition" jsonb NOT NULL,
  "category" text NOT NULL,
  "enabled" boolean NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."achievement_rules" IS 'Версия достижения. 50+ достижений; каталог/веса ещё не утверждены';

CREATE TABLE meal."achievement_awards" (
  "id" uuid NOT NULL PRIMARY KEY,
  "awarded_at" timestamptz NOT NULL,
  "revoked_at" timestamptz,
  "evidence" jsonb NOT NULL,
  "user_id" uuid NOT NULL,
  "rule_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."achievement_awards" IS 'Полученное достижение. Идемпотентная выдача по правилу и qualifying event';

CREATE TABLE meal."reputation_events" (
  "id" uuid NOT NULL PRIMARY KEY,
  "delta" bigint NOT NULL,
  "rule_version" text NOT NULL,
  "reason" text NOT NULL,
  "evidence" jsonb NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "user_id" uuid NOT NULL,
  "reverses_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."reputation_events" IS 'Изменение репутации. Append-only; формула не фиксируется до согласования';

CREATE TABLE meal."moderation_cases" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "reason" text NOT NULL,
  "submitted_at" timestamptz NOT NULL,
  "queue_priority" integer NOT NULL,
  "evidence" jsonb NOT NULL,
  "reporter_id" uuid,
  "recipe_revision_id" uuid,
  "catalog_proposal_revision_id" uuid,
  "comment_id" uuid,
  "asset_id" uuid,
  "assigned_to" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."moderation_cases" IS 'Проверка контента или жалоба. Ровно одна цель в проверке контента; анонимность заявителя перед автором';

CREATE TABLE meal."moderation_correspondence" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "body" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "internal" boolean NOT NULL,
  "idempotency_key" text NOT NULL,
  "case_id" uuid NOT NULL,
  "author_id" uuid NOT NULL,
  "reply_to_id" uuid,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."moderation_correspondence" IS 'Уточнение по жалобе. Ответ связан с конкретным вопросом той же жалобы; внутреннее не выдаётся автору контента';

CREATE TABLE meal."moderation_claims" (
  "id" uuid NOT NULL PRIMARY KEY,
  "claimed_at" timestamptz NOT NULL,
  "lease_until" timestamptz NOT NULL,
  "released_at" timestamptz,
  "outcome" text,
  "case_id" uuid NOT NULL,
  "staff_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."moderation_claims" IS 'История захвата очереди. Очередь — проекция cases; claim не решение, пропуск не отказ и не удаление';

CREATE TABLE meal."moderation_decisions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "action" text NOT NULL,
  "reason" text NOT NULL,
  "decided_at" timestamptz NOT NULL,
  "before_snapshot" jsonb NOT NULL,
  "after_snapshot" jsonb NOT NULL,
  "case_id" uuid NOT NULL,
  "actor_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."moderation_decisions" IS 'Решение проверки. Автосигнал и ручная публикация различны; публикация только staff';

CREATE TABLE meal."sanctions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "scope" text NOT NULL,
  "starts_at" timestamptz NOT NULL,
  "ends_at" timestamptz,
  "reason" text NOT NULL,
  "revoked_at" timestamptz,
  "rule_version" text NOT NULL,
  "user_id" uuid NOT NULL,
  "issued_by" uuid,
  "case_id" uuid,
  "safety_event_id" uuid,
  "approved_by" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."sanctions" IS 'Ограничение пользователя. AI/account/publication не один ban; тяжёлые AI-санкции с ручным решением';

CREATE TABLE meal."appeals" (
  "id" uuid NOT NULL PRIMARY KEY,
  "body" text NOT NULL,
  "status" text NOT NULL,
  "submitted_at" timestamptz NOT NULL,
  "resolved_at" timestamptz,
  "decision" jsonb,
  "user_id" uuid NOT NULL,
  "sanction_id" uuid,
  "moderation_decision_id" uuid,
  "ticket_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."appeals" IS 'Апелляция. Ровно один обжалуемый результат; отмена сохраняет историю';

CREATE TABLE meal."media_assets" (
  "id" uuid NOT NULL PRIMARY KEY,
  "object_key" text NOT NULL,
  "mime" text NOT NULL,
  "size_bytes" bigint NOT NULL,
  "checksum" text NOT NULL,
  "status" text NOT NULL,
  "alt_text" text,
  "retention_class" text NOT NULL,
  "uploader_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."media_assets" IS 'Метаданные файла. Бинарные файлы во внешнем хранилище; object_key не публичный URL';

CREATE TABLE meal."media_variants" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "object_key" text NOT NULL,
  "mime" text NOT NULL,
  "size_bytes" bigint NOT NULL,
  "width" integer,
  "height" integer,
  "duration" integer,
  "asset_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."media_variants" IS 'Оптимизированная версия файла. Исходник и производные отдельны; private не становится public после обработки';

CREATE TABLE meal."media_processing_runs" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "provider" text,
  "policy_version" text NOT NULL,
  "result" jsonb,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "asset_id" uuid NOT NULL,
  "job_id" uuid,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."media_processing_runs" IS 'Проверка и обработка медиа. Upload/scan/moderation/transcode различны; неопроверенное медиа не публикуется';

CREATE TABLE meal."media_links" (
  "id" uuid NOT NULL PRIMARY KEY,
  "position" integer NOT NULL,
  "slot" text NOT NULL,
  "asset_id" uuid NOT NULL,
  "receipt_id" uuid,
  "note_id" uuid,
  "recipe_revision_id" uuid,
  "diary_entry_id" uuid,
  "chat_message_id" uuid,
  "support_message_id" uuid,
  "comment_id" uuid,
  "catalog_proposal_id" uuid,
  "announcement_id" uuid,
  "product_id" uuid,
  "batch_id" uuid,
  "avatar_user_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."media_links" IS 'Использование файла в объекте. Ровно один родитель; ACL по нему; private asset нельзя переиспользовать в public без разрешения';

CREATE TABLE meal."recognition_jobs" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "provider_policy" text NOT NULL,
  "external_consent_at" timestamptz,
  "result_snapshot" jsonb,
  "user_id" uuid NOT NULL,
  "scope_id" uuid NOT NULL,
  "receipt_id" uuid,
  "proposal_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recognition_jobs" IS 'OCR и разбор источника. Генеративный AI не обязательный шаг Free OCR; применение после review';

CREATE TABLE meal."recognition_sources" (
  "id" uuid NOT NULL PRIMARY KEY,
  "slot" text NOT NULL,
  "source_url" text,
  "captured_at" timestamptz,
  "job_id" uuid NOT NULL,
  "asset_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recognition_sources" IS 'Снимок/документ OCR. Указан asset либо проверенный источник ссылки; SSRF-защита backend';

CREATE TABLE meal."recognition_fields" (
  "id" uuid NOT NULL PRIMARY KEY,
  "path" text NOT NULL,
  "raw_value" jsonb NOT NULL,
  "confidence" numeric(24,8),
  "reviewed_value" jsonb,
  "reviewed_at" timestamptz,
  "conflict" boolean NOT NULL,
  "job_id" uuid NOT NULL,
  "source_id" uuid,
  "reviewed_by" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."recognition_fields" IS 'Распознанное поле и правка. Несколько источников не смешиваются молча; сохраняется происхождение каждого поля';

CREATE TABLE meal."import_jobs" (
  "id" uuid NOT NULL PRIMARY KEY,
  "format" text NOT NULL,
  "status" text NOT NULL,
  "input_hash" text NOT NULL,
  "preview" jsonb NOT NULL,
  "commit_policy" text NOT NULL,
  "user_id" uuid NOT NULL,
  "scope_id" uuid NOT NULL,
  "asset_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."import_jobs" IS 'Импорт таблицы запасов. CSV/TSV/XLSX/ODS; atomic/partial ещё TECH-01, не выбирать поведением схемы';

CREATE TABLE meal."import_sheets" (
  "id" uuid NOT NULL PRIMARY KEY,
  "source_key" text NOT NULL,
  "name" text NOT NULL,
  "position" integer NOT NULL,
  "header_row" integer,
  "mapping" jsonb NOT NULL,
  "selected" boolean NOT NULL,
  "job_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."import_sheets" IS 'Лист и сопоставление колонок. Уникально job+source_key; для CSV один лист';

CREATE TABLE meal."import_rows" (
  "id" uuid NOT NULL PRIMARY KEY,
  "row_number" integer NOT NULL,
  "raw" jsonb NOT NULL,
  "normalized" jsonb NOT NULL,
  "errors" jsonb NOT NULL,
  "status" text NOT NULL,
  "sheet_id" uuid NOT NULL,
  "operation_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."import_rows" IS 'Результат строки импорта. Уникально sheet+row; защита от повторного поступления';

CREATE TABLE meal."export_jobs" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "format" text NOT NULL,
  "period" text NOT NULL,
  "status" text NOT NULL,
  "manifest" jsonb NOT NULL,
  "requested_at" timestamptz NOT NULL,
  "expires_at" timestamptz,
  "user_id" uuid NOT NULL,
  "scope_id" uuid,
  "file_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."export_jobs" IS 'Запрос выгрузки. Состав ограничен ACL; доступ к скачиванию проверяется заново';

CREATE TABLE meal."audit_events" (
  "id" uuid NOT NULL PRIMARY KEY,
  "action" text NOT NULL,
  "target_type" text NOT NULL,
  "target_id" uuid NOT NULL,
  "effective_at" timestamptz NOT NULL,
  "recorded_at" timestamptz NOT NULL,
  "reason" text,
  "before_redacted" jsonb,
  "after_redacted" jsonb,
  "request_id" uuid NOT NULL,
  "actor_id" uuid,
  "scope_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."audit_events" IS 'Аудит действия. Append-only; target_type/id только аудит, не источник прав и не замена доменным FK';

CREATE TABLE meal."compensation_requests" (
  "id" uuid NOT NULL PRIMARY KEY,
  "mode" text NOT NULL,
  "status" text NOT NULL,
  "preview" jsonb NOT NULL,
  "reason" text NOT NULL,
  "applied_at" timestamptz,
  "requested_by" uuid NOT NULL,
  "scope_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."compensation_requests" IS 'План и результат отката. Family batch только свои действия атомарно; admin может иметь частичный результат';

CREATE TABLE meal."compensation_items" (
  "id" uuid NOT NULL PRIMARY KEY,
  "status" text NOT NULL,
  "dependency_snapshot" jsonb NOT NULL,
  "result" jsonb NOT NULL,
  "request_id" uuid NOT NULL,
  "source_event_id" uuid NOT NULL,
  "result_event_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."compensation_items" IS 'Зависимость и результат отката. Поздние чужие правки не затираются; доменный эффект отдельной компенсирующей операцией';

CREATE TABLE meal."idempotency_records" (
  "id" uuid NOT NULL PRIMARY KEY,
  "operation" text NOT NULL,
  "target_binding" text NOT NULL,
  "key" text NOT NULL,
  "request_hash" text NOT NULL,
  "status" text NOT NULL,
  "response_snapshot" jsonb,
  "expires_at" timestamptz NOT NULL,
  "user_id" uuid,
  "scope_id" uuid,
  "actor_namespace" text NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."idempotency_records" IS 'Результат повторяемой команды. Уникальность actor+operation+target+key; system actor имеет отдельный namespace; права проверяются при replay';

CREATE TABLE meal."outbox_events" (
  "id" uuid NOT NULL PRIMARY KEY,
  "type" text NOT NULL,
  "payload_minimized" jsonb NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "published_at" timestamptz,
  "attempts" integer NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."outbox_events" IS 'Доставка доменного события. В одной транзакции с доменными изменениями; доставка может повторяться';

CREATE TABLE meal."background_jobs" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "run_at" timestamptz NOT NULL,
  "lease_until" timestamptz,
  "dedup_key" text NOT NULL,
  "payload_minimized" jsonb NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."background_jobs" IS 'Устойчивая фоновая задача. Один источник очереди; физическая таблица может принадлежать выбранному queue engine';

CREATE TABLE meal."job_attempts" (
  "id" uuid NOT NULL PRIMARY KEY,
  "attempt_no" integer NOT NULL,
  "started_at" timestamptz NOT NULL,
  "finished_at" timestamptz,
  "error_redacted" jsonb,
  "job_id" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."job_attempts" IS 'Попытка фоновой задачи. Повтор задачи не повторяет бизнес-эффект';

CREATE TABLE meal."sync_conflicts" (
  "id" uuid NOT NULL PRIMARY KEY,
  "entity_type" text NOT NULL,
  "entity_id" uuid NOT NULL,
  "base_version" bigint NOT NULL,
  "server_snapshot" jsonb NOT NULL,
  "client_snapshot" jsonb NOT NULL,
  "status" text NOT NULL,
  "user_id" uuid NOT NULL,
  "scope_id" uuid NOT NULL,
  "idempotency_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."sync_conflicts" IS 'Неразрешённый конфликт sync. Обе версии сохранены; клиентское время не определяет победителя';

CREATE TABLE meal."user_hidden_objects" (
  "id" uuid NOT NULL PRIMARY KEY,
  "hidden_at" timestamptz NOT NULL,
  "user_id" uuid NOT NULL,
  "note_id" uuid,
  "batch_id" uuid,
  "recipe_id" uuid,
  "chat_message_id" uuid,
  "comment_id" uuid,
  "receipt_id" uuid,
  "purchase_id" uuid,
  "plan_id" uuid,
  "membership_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."user_hidden_objects" IS 'Скрытие только у себя. Ровно один объект; скрытие не меняет общие итоги и чужие ACL';

CREATE TABLE meal."feature_rule_versions" (
  "id" uuid NOT NULL PRIMARY KEY,
  "key" text NOT NULL,
  "version" bigint NOT NULL,
  "enabled" boolean NOT NULL,
  "rules" jsonb NOT NULL,
  "effective_at" timestamptz NOT NULL,
  "changed_by" uuid NOT NULL,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);
COMMENT ON TABLE meal."feature_rule_versions" IS 'Конфигурация функции/лимита. История акций, лимитов и stop-loss; секреты вне этой таблицы';

CREATE TABLE meal."legal_requests" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "scope_snapshot" jsonb NOT NULL,
  "retention_basis" jsonb NOT NULL,
  "approved_at" timestamptz,
  "executed_at" timestamptz,
  "user_id" uuid NOT NULL,
  "handled_by" uuid,
  "export_id" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."legal_requests" IS 'Юридическая процедура. Удаление не CASCADE по user; учитываются права других и финансы';

CREATE TABLE meal."legal_request_steps" (
  "id" uuid NOT NULL PRIMARY KEY,
  "kind" text NOT NULL,
  "status" text NOT NULL,
  "evidence" jsonb NOT NULL,
  "completed_at" timestamptz,
  "request_id" uuid NOT NULL,
  "approved_by" uuid,
  "created_at" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "version" bigint NOT NULL DEFAULT 1
);
COMMENT ON TABLE meal."legal_request_steps" IS 'Проверка зависимости удаления. Экспорт, владение, retention, refund и подтверждения различны';
