-- Writes must use SERIALIZABLE transactions; backend retries SQLSTATE 40001/40P01.
-- This also protects cross-row constraints from write skew. No SECURITY DEFINER.
CREATE FUNCTION meal.require_serializable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF current_setting('transaction_isolation') <> 'serializable' THEN
  RAISE EXCEPTION 'meal writes require SERIALIZABLE transaction' USING ERRCODE='25000';
 END IF;
 RETURN NULL;
END $$;

CREATE FUNCTION meal.reject_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'append-only relation %.%; use a new revision/compensation',TG_TABLE_SCHEMA,TG_TABLE_NAME USING ERRCODE='23514'; END $$;

CREATE FUNCTION meal.link_value(row_data jsonb, field_name text, parent_table text, parent_column text)
RETURNS text LANGUAGE plpgsql STABLE AS $$
DECLARE result text;
BEGIN
 IF parent_table='@self' THEN RETURN row_data->>field_name; END IF;
 EXECUTE format('SELECT %I::text FROM meal.%I WHERE id=$1',parent_column,parent_table)
 INTO result USING (row_data->>field_name)::uuid;
 RETURN result;
END $$;

CREATE FUNCTION meal.check_link_pair() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE row_data jsonb; a text; b text;
BEGIN
 -- Re-read final row: deferred NEW may describe an earlier update in this transaction.
 EXECUTE format('SELECT to_jsonb(t) FROM meal.%I t WHERE id=$1',TG_TABLE_NAME) INTO row_data USING NEW.id;
 IF row_data IS NULL OR row_data->>TG_ARGV[0] IS NULL OR row_data->>TG_ARGV[3] IS NULL THEN RETURN NULL; END IF;
 a:=meal.link_value(row_data,TG_ARGV[0],TG_ARGV[1],TG_ARGV[2]);
 b:=meal.link_value(row_data,TG_ARGV[3],TG_ARGV[4],TG_ARGV[5]);
 IF a IS DISTINCT FROM b OR a IS NULL THEN RAISE EXCEPTION 'cross-owner/parent link on %: % vs %',TG_TABLE_NAME,TG_ARGV[0],TG_ARGV[3] USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;

CREATE FUNCTION meal.check_families() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM meal.families f LEFT JOIN meal.family_memberships m ON m.id=f.owner_membership_id
 WHERE f.status='active' AND (m.id IS NULL OR m.family_id<>f.id OR m.left_at IS NOT NULL)) THEN
  RAISE EXCEPTION 'active family needs an active owner membership in the same family' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.family_memberships m JOIN meal.families f ON f.id=m.family_id WHERE m.left_at IS NULL AND f.status<>'active') THEN
  RAISE EXCEPTION 'archived family cannot have active members' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.family_memberships m JOIN meal.family_profiles p ON p.id=m.profile_id
 WHERE p.family_id<>m.family_id OR p.linked_user_id IS DISTINCT FROM m.user_id) THEN
  RAISE EXCEPTION 'membership/profile mismatch' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT holder_id FROM meal.family_slot_grants WHERE revoked_at IS NULL AND accepted_at IS NOT NULL GROUP BY holder_id HAVING count(*)>2) THEN
  RAISE EXCEPTION 'at most two permanent slot grants' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.family_slot_grants s JOIN meal.families f ON f.id=s.family_id JOIN meal.family_memberships m ON m.id=f.owner_membership_id
 WHERE s.revoked_at IS NULL AND s.accepted_at IS NOT NULL AND f.status='active' AND s.holder_id<>m.user_id) THEN
  RAISE EXCEPTION 'family slots must follow owner' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.families f JOIN meal.family_memberships owner_m ON owner_m.id=f.owner_membership_id WHERE f.status='active'
 AND (SELECT count(*) FROM meal.family_memberships m WHERE m.family_id=f.id AND m.left_at IS NULL) >
 4 + coalesce((SELECT sum(s.seats) FROM meal.family_slot_grants s WHERE s.holder_id=owner_m.user_id AND s.revoked_at IS NULL AND s.accepted_at IS NOT NULL),0)) THEN
  RAISE EXCEPTION 'family account capacity exceeded' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER family_integrity AFTER INSERT OR UPDATE OR DELETE ON meal.families DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_families();
CREATE CONSTRAINT TRIGGER family_integrity AFTER INSERT OR UPDATE OR DELETE ON meal.family_memberships DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_families();
CREATE CONSTRAINT TRIGGER family_integrity AFTER INSERT OR UPDATE OR DELETE ON meal.family_profiles DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_families();
CREATE CONSTRAINT TRIGGER family_integrity AFTER INSERT OR UPDATE OR DELETE ON meal.family_slot_grants DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_families();

CREATE FUNCTION meal.protect_last_admin() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.role='admin' AND OLD.revoked_at IS NULL AND NOT EXISTS(SELECT 1 FROM meal.staff_role_assignments a JOIN meal.users u ON u.id=a.user_id WHERE a.role='admin' AND a.revoked_at IS NULL AND u.status='active') THEN
  RAISE EXCEPTION 'cannot remove last active administrator' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER protect_last_admin AFTER UPDATE OR DELETE ON meal.staff_role_assignments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.protect_last_admin();
CREATE FUNCTION meal.protect_admin_account() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM meal.staff_role_assignments WHERE user_id=OLD.id AND role='admin' AND revoked_at IS NULL)
 AND NOT EXISTS(SELECT 1 FROM meal.staff_role_assignments a JOIN meal.users u ON u.id=a.user_id WHERE a.role='admin' AND a.revoked_at IS NULL AND u.status='active') THEN
 RAISE EXCEPTION 'cannot disable last active administrator' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER protect_admin_account AFTER UPDATE OR DELETE ON meal.users DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.protect_admin_account();

CREATE FUNCTION meal.protect_scope_and_identity() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE old_row jsonb:=to_jsonb(OLD); new_row jsonb:=to_jsonb(NEW); field text;
BEGIN
 IF NEW.id<>OLD.id THEN RAISE EXCEPTION 'entity id is immutable' USING ERRCODE='23514'; END IF;
 FOREACH field IN ARRAY ARRAY['scope_id','author_id','owner_id','recipient_id','user_id','family_id','batch_id','operation_id','attempt_id','recipe_id','revision_id','thread_id','message_id','profile_id','note_id','purchase_id','bucket_id','conversation_id','task_id','interval_id','entry_id','sheet_id','job_id','ingredient_id','variant_id','product_id'] LOOP
  -- Explicit workflows may change members/holders/assignees, not the identity/scope of an existing record.
  IF TG_TABLE_NAME NOT IN ('subscriptions','family_slot_grants','family_profiles') AND old_row ? field AND old_row->field IS DISTINCT FROM new_row->field THEN
   RAISE EXCEPTION 'immutable identity link %.%; create explicit replacement/workflow',TG_TABLE_NAME,field USING ERRCODE='23514';
  END IF;
 END LOOP;
 RETURN NEW;
END $$;

CREATE FUNCTION meal.check_cooking_evidence() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE row_data jsonb; actual_recipe uuid; cooking_status text; completed timestamptz;
BEGIN
 EXECUTE format('SELECT to_jsonb(t) FROM meal.%I t WHERE id=$1',TG_TABLE_NAME) INTO row_data USING NEW.id;
 IF row_data IS NULL THEN RETURN NULL; END IF;
 SELECT r.recipe_id,a.status,a.completed_at INTO actual_recipe,cooking_status,completed
 FROM meal.cooking_attempts a JOIN meal.recipe_revisions r ON r.id=a.revision_id WHERE a.id=(row_data->>'attempt_id')::uuid;
 IF actual_recipe IS DISTINCT FROM (row_data->>'recipe_id')::uuid OR cooking_status IS DISTINCT FROM 'completed' OR completed IS NULL THEN
  RAISE EXCEPTION 'rating/comment requires a completed attempt of the same recipe' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER cooking_evidence AFTER INSERT OR UPDATE ON meal.recipe_ratings DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_cooking_evidence();
CREATE CONSTRAINT TRIGGER cooking_evidence AFTER INSERT OR UPDATE ON meal.recipe_comments DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_cooking_evidence();
CREATE FUNCTION meal.protect_completed_cooking() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.status='completed' AND (NEW.status<>'completed' OR NEW.completed_at IS DISTINCT FROM OLD.completed_at OR NEW.recipe_snapshot IS DISTINCT FROM OLD.recipe_snapshot) THEN
 RAISE EXCEPTION 'completed cooking is historical; create compensation/new attempt' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER completed_cooking BEFORE UPDATE ON meal.cooking_attempts FOR EACH ROW EXECUTE FUNCTION meal.protect_completed_cooking();

CREATE FUNCTION meal.check_ai_balances() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM meal.ai_buckets b LEFT JOIN (SELECT bucket_id,sum(delta) balance,sum(reserved_delta) reserved FROM meal.ai_ledger GROUP BY bucket_id) l ON l.bucket_id=b.id
 WHERE b.balance_projection<>coalesce(l.balance,0) OR b.reserved_projection<>coalesce(l.reserved,0)) THEN
 RAISE EXCEPTION 'AI projection must equal append-only ledger' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER ai_balances AFTER INSERT OR UPDATE OR DELETE ON meal.ai_buckets DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_ai_balances();
CREATE CONSTRAINT TRIGGER ai_balances AFTER INSERT OR UPDATE OR DELETE ON meal.ai_ledger DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_ai_balances();

CREATE FUNCTION meal.check_intake_and_allocations() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS(SELECT 1 FROM meal.stock_intakes i JOIN meal.purchase_lines l ON l.id=i.purchase_line_id JOIN meal.purchases p ON p.id=l.purchase_id JOIN meal.inventory_batches b ON b.id=i.batch_id WHERE b.scope_id<>p.scope_id) THEN
 RAISE EXCEPTION 'purchase intake crosses data scope' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.shopping_allocations a JOIN meal.shopping_items i ON i.id=a.item_id JOIN meal.shopping_lists s ON s.id=i.list_id JOIN meal.purchase_lines l ON l.id=a.purchase_line_id JOIN meal.purchases p ON p.id=l.purchase_id WHERE s.scope_id<>p.scope_id) THEN
 RAISE EXCEPTION 'shopping allocation crosses data scope' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.purchase_lines l JOIN (SELECT purchase_line_id,sum(quantity) q FROM meal.stock_intakes GROUP BY purchase_line_id) i ON i.purchase_line_id=l.id WHERE l.quantity IS NULL OR i.q>l.quantity) THEN
 RAISE EXCEPTION 'intake exceeds known purchased quantity' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.purchase_lines l JOIN (SELECT purchase_line_id,sum(quantity) q FROM meal.shopping_allocations GROUP BY purchase_line_id) a ON a.purchase_line_id=l.id WHERE l.quantity IS NULL OR a.q>l.quantity) THEN
 RAISE EXCEPTION 'allocation exceeds known purchased quantity' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER intake_allocations AFTER INSERT OR UPDATE OR DELETE ON meal.stock_intakes DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_intake_and_allocations();
CREATE CONSTRAINT TRIGGER intake_allocations AFTER INSERT OR UPDATE OR DELETE ON meal.shopping_allocations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_intake_and_allocations();
CREATE CONSTRAINT TRIGGER intake_allocations AFTER UPDATE ON meal.purchase_lines DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_intake_and_allocations();

CREATE FUNCTION meal.check_portion_transition() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF OLD.state<>NEW.state AND NOT ((OLD.state='pending' AND NEW.state IN ('confirmed','auto_confirmed','refused')) OR (OLD.state='auto_confirmed' AND NEW.state='cancelled')) THEN
  RAISE EXCEPTION 'invalid portion transition % -> %',OLD.state,NEW.state USING ERRCODE='23514'; END IF;
 IF OLD.available_at<>NEW.available_at OR OLD.due_at<>NEW.due_at OR OLD.allocation_key<>NEW.allocation_key OR OLD.issued_quantity<>NEW.issued_quantity OR OLD.allocation_operation_id<>NEW.allocation_operation_id THEN
  RAISE EXCEPTION 'portion allocation and timer are immutable' USING ERRCODE='23514'; END IF;
 RETURN NEW;
END $$;
CREATE TRIGGER portion_transition BEFORE UPDATE ON meal.portion_proposals FOR EACH ROW EXECUTE FUNCTION meal.check_portion_transition();

CREATE FUNCTION meal.check_combinations() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
 IF EXISTS(SELECT source_id FROM (SELECT first_subscription_id source_id FROM meal.subscription_combinations WHERE status='applied' UNION ALL SELECT second_subscription_id FROM meal.subscription_combinations WHERE status='applied') s GROUP BY source_id HAVING count(*)>1) THEN
  RAISE EXCEPTION 'Plus source already consumed by a combination' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM meal.subscription_combinations c LEFT JOIN meal.subscriptions a ON a.id=c.first_subscription_id LEFT JOIN meal.subscriptions b ON b.id=c.second_subscription_id LEFT JOIN meal.subscriptions p ON p.id=c.result_subscription_id LEFT JOIN meal.billing_products ap ON ap.id=a.product_id LEFT JOIN meal.billing_products bp ON bp.id=b.product_id LEFT JOIN meal.billing_products pp ON pp.id=p.product_id
 WHERE c.status='applied' AND (a.status IS DISTINCT FROM 'combined' OR b.status IS DISTINCT FROM 'combined' OR a.auto_renew OR b.auto_renew OR p.owner_id IS DISTINCT FROM c.recipient_id OR ap.code IS DISTINCT FROM 'plus' OR bp.code IS DISTINCT FROM 'plus' OR pp.code IS DISTINCT FROM 'pro' OR NOT EXISTS(SELECT 1 FROM meal.subscription_periods sp WHERE sp.subscription_id=p.id AND sp.grant_kind='combination' AND sp.ends_at=greatest(c.source_end_1,c.source_end_2)))) THEN
  RAISE EXCEPTION 'invalid resulting combined Pro/terminated Plus' USING ERRCODE='23514'; END IF;
 RETURN NULL;
END $$;
CREATE CONSTRAINT TRIGGER check_combinations AFTER INSERT OR UPDATE OR DELETE ON meal.subscription_combinations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_combinations();
CREATE CONSTRAINT TRIGGER check_combinations AFTER INSERT OR UPDATE OR DELETE ON meal.subscriptions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_combinations();
CREATE CONSTRAINT TRIGGER check_combinations AFTER INSERT OR UPDATE OR DELETE ON meal.subscription_periods DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION meal.check_combinations();

